  "rules": [
    {
      "id": "R1",
      "ruleQuote": "이때 정해진 절차에 어긋나거나 법인의 목적과는 다르게 자산을 운용하면 법적으로 처벌받을 수 있다.",
      "statement": "법인 자산의 운용이 정해진 절차에 어긋나거나 법인의 목적과 다르면 법적 처벌의 대상이 될 수 있다.",
      "variables": [
        {
          "name": "정해진 절차의 위반 여부",
          "effect": "정해진 절차에 어긋나게 자산을 운용하면 법적으로 처벌받을 수 있다."
        },
        {
          "name": "법인의 목적과 다른 운용 여부",
          "effect": "법인의 목적과 다르게 자산을 운용하면 법적으로 처벌받을 수 있다."
        }
      ],
      "scopeQuote": "실제 자산의 운용은 법인의 정관*이나 법령에서 권한을 부여한 사람에 의해 이루어진다.",
      "statedApplications": [],
      "openSlots": []
    },
    {
      "id": "R2",
      "ruleQuote": "특히 법인의 목적 사업 수행을 위한 자산인 기본 재산은 재단을 설립할 때 정관에 기재해 등기해야 하고, 이를 처분하거나 용도를 변경하여 액수를 줄이려면 반드시 관할 기관의 허가가 필요하다.",
      "statement": "재단 법인의 기본 재산을 처분하거나 용도를 변경하여 액수를 줄이려면 관할 기관의 허가를 받아야 한다.",
      "variables": [
        {
          "name": "기본 재산에 대한 운용 행위",
          "effect": "기본 재산을 처분하거나 용도를 변경하여 액수를 줄이는 행위에는 관할 기관의 허가가 필요하다."
        }
      ],
      "scopeQuote": "재단 법인의 이사회는 결정권자가 아니며 주요 사항을 결정할 때는 반드시 관할 기관의 허가를 받아야 한다.",
      "statedApplications": [],
      "openSlots": []
    },
    {
      "id": "R3",
      "ruleQuote": "자본금은 주식을 발행하여 조달된 자금으로, 발행된 총 주식 수에 주식의 액면가*를 곱한 금액이다.",
      "statement": "주식회사의 자본금은 발행된 총 주식 수와 주식의 액면가를 곱하여 산출한다.",
      "variables": [
        {
          "name": "발행된 총 주식 수",
          "effect": "액면가가 같으면 발행된 총 주식 수에 비례하여 자본금이 달라진다."
        },
        {
          "name": "주식의 액면가",
          "effect": "발행된 총 주식 수가 같으면 액면가에 비례하여 자본금이 달라진다."
        }
      ],
      "scopeQuote": "주식회사의 자산은 주주의 출자에 의해 형성되며 자본금, 이익 잉여금, 자본 잉여금 등의 항목으로 구성된다.",
      "statedApplications": [],
      "openSlots": [
        {
          "id": "R3-S1",
          "target": "무상 증자를 실시한 주식회사의 자본금",
          "quote": "주식회사는 무상 증자를 실시하여 자본 잉여금이나 이익 잉여금의 일부 혹은 전부에 해당하는 만큼의 주식을 추가로 발행하여 주주들에게 무상으로 분배한다.",
          "whatToDerive": "무상 증자로 추가 발행하는 주식 수와 액면가를 바탕으로 자본금이 어떻게 달라지는지 알아낼 수 있다."
        }
      ]
    },
    {
      "id": "R4",
      "ruleQuote": "이는 회사의 지급 능력과 재무 안정성을 보장하는 기초 자산이므로 원칙적으로 감액이 금지된다. 이익 잉여금은 영업 활동에서 발생한 이익 중 사용되지 않고 유보된 재원으로, 주주들에게 이익을 분배하는 행위인 배당을 통해 배당금으로 지급되거나 사업 투자, 손실 보전 등을 목적으로 비교적 자유롭게 활용될 수 있다. 자본 잉여금은 주식 등 자본을 거래하여 얻은 이익으로 손실 보전 등의 제한된 목적으로만 사용될 수 있고, 배당금으로 지급될 수 없다.",
      "statement": "주식회사의 자산은 항목에 따라 운용 제한이 달라서 자본금은 원칙적으로 감액할 수 없고, 이익 잉여금은 배당·사업 투자·손실 보전 등에 비교적 자유롭게 활용할 수 있으며, 자본 잉여금은 배당할 수 없고 손실 보전 등의 제한된 목적으로만 사용할 수 있다.",
      "variables": [
        {
          "name": "운용하려는 자산의 항목",
          "effect": "자본금이면 원칙적으로 감액이 금지되고, 이익 잉여금이면 배당·사업 투자·손실 보전 등에 비교적 자유롭게 사용할 수 있으며, 자본 잉여금이면 배당이 금지되고 사용 목적이 제한된다."
        },
        {
          "name": "자산의 사용 목적",
          "effect": "배당에는 이익 잉여금을 사용할 수 있지만 자본 잉여금은 사용할 수 없고, 손실 보전에는 이익 잉여금과 자본 잉여금을 사용할 수 있다."
        }
      ],
      "scopeQuote": "주식회사의 자산은 주주의 출자에 의해 형성되며 자본금, 이익 잉여금, 자본 잉여금 등의 항목으로 구성된다.",
      "statedApplications": [],
      "openSlots": []
    },
    {
      "id": "R5",
      "ruleQuote": "주식회사의 자산 운용은 각 항목의 특성에 따라 이익을 극대화하는 방향으로 이루어지는데, 적자가 누적되어 이익 잉여금이나 자본 잉여금으로도 손실을 보전할 수 없는 경우에는 자본금을 사용하게 된다.",
      "statement": "적자가 누적되어 이익 잉여금이나 자본 잉여금으로도 손실을 보전할 수 없으면 자본금을 사용하게 된다.",
      "variables": [
        {
          "name": "이익 잉여금이나 자본 잉여금으로 손실을 보전할 수 있는지 여부",
          "effect": "누적된 적자를 이익 잉여금이나 자본 잉여금으로도 보전할 수 없으면 자본금을 사용하게 된다."
        }
      ],
      "scopeQuote": "주식회사의 자산 운용은 각 항목의 특성에 따라 이익을 극대화하는 방향으로 이루어지는데",
      "statedApplications": [],
      "openSlots": []
    },
    {
      "id": "R6",
      "ruleQuote": "주식회사는 무상 증자를 실시하여 자본 잉여금이나 이익 잉여금의 일부 혹은 전부에 해당하는 만큼의 주식을 추가로 발행하여 주주들에게 무상으로 분배한다.",
      "statement": "무상 증자에서는 자본 잉여금이나 이익 잉여금 중 사용하는 금액에 해당하는 만큼의 주식을 추가 발행하여 주주들에게 무상으로 분배한다.",
      "variables": [
        {
          "name": "무상 증자에 사용하는 자본 잉여금 또는 이익 잉여금의 금액",
          "effect": "사용하는 금액에 해당하는 만큼의 주식이 추가로 발행되어 주주들에게 무상으로 분배된다."
        }
      ],
      "scopeQuote": "주식회사는 무상 증자를 실시하여",
      "statedApplications": [],
      "openSlots": []
    },
    {
      "id": "R7",
      "ruleQuote": "무상 증자를 실행하면 자산의 구조만 재편되고 자산의 총 규모는 변하지 않기 때문에 이사회의 결정만으로 실행이 가능하다. 배당은 주주의 만족도를 높일 수 있고 회사는 추가적인 투자를 기대할 수 있다. 다만 배당은 자산이 외부로 유출되는 것이기 때문에, 잘못된 판단으로 인한 회사나 주주들의 손해를 막기 위해 이사회뿐만 아니라 주주 총회의 의결을 거치는 등 더 까다로운 요건을 만족해야 한다.",
      "statement": "주식회사의 자산 운용은 외부 유출 여부에 따라 실행 요건이 달라져, 자산 총규모가 변하지 않는 무상 증자는 이사회의 결정만으로 가능하지만 자산이 외부로 유출되는 배당은 주주 총회의 의결 등 더 까다로운 요건을 충족해야 한다.",
      "variables": [
        {
          "name": "자산의 외부 유출 여부",
          "effect": "자산 총규모가 변하지 않는 무상 증자는 이사회의 결정만으로 실행할 수 있지만, 외부 유출이 발생하는 배당은 이사회뿐 아니라 주주 총회의 의결을 거치는 등 더 까다로운 요건이 필요하다."
        }
      ],
      "scopeQuote": "주식회사의 자산 운용은 자산의 외부 유출 여부에 따라 실행의 요건이 다르다.",
      "statedApplications": [
        {
          "target": "무상 증자",
          "quote": "무상 증자를 실행하면 자산의 구조만 재편되고 자산의 총 규모는 변하지 않기 때문에 이사회의 결정만으로 실행이 가능하다."
        },
        {
          "target": "배당",
          "quote": "다만 배당은 자산이 외부로 유출되는 것이기 때문에, 잘못된 판단으로 인한 회사나 주주들의 손해를 막기 위해 이사회뿐만 아니라 주주 총회의 의결을 거치는 등 더 까다로운 요건을 만족해야 한다."
        }
      ],
      "openSlots": []
    }
  ]
}

